/**
 * Arithmetic in the Galois field GF(256) used by QR-code error correction.
 * The field is generated by the primitive polynomial x^8 + x^4 + x^3 + x^2 + 1.
 */
class GaloisField256 {
  static PRIMITIVE_POLYNOMIAL = 0x11d;

  static multiply(left, right) {
    let product = 0;
    for (let position = 7; position >= 0; position--) {
      product = (product << 1) ^ ((product >>> 7) * this.PRIMITIVE_POLYNOMIAL);
      product ^= ((right >>> position) & 1) * left;
    }
    return product & 0xff;
  }
}
